VID.narration = {"look":{"bar":false},"scenes":[{"dur":7.616,"caps":[[0.5,6.27,"Phase seven. Information theory and compression. This is how files get smaller."]],"warp":[[0,0],[0.5,0.9],[7.616,4]]},{"dur":21.688,"caps":[[0.5,5.47,"A fixed code spends 3 bits on every letter."],[5.72,10.45,"That is 21 bits for BBADEBC."],[10.7,15.35,"But B turns up three times."],[15.6,20.41,"Common letters get short codes: 15 bits."]],"warp":[[0,0],[0.5,0.4],[5.72,3.8],[10.7,5.8],[15.6,7.9],[21.688,10]]},{"dur":18.343,"caps":[[0.5,5.15,"News we expect tells us nothing: 0 bits."],[5.4,9.73,"Half the chance: one yes-or-no answer, 1 bit."],[9.98,13.51,"Each time the chance halves, one more bit."],[13.76,16.81,"Rarer news tells us more."]],"warp":[[0,0],[0.5,0.4],[5.4,2.8],[9.98,5.1],[13.76,8.8],[18.343,11]]},{"dur":31.719,"caps":[[0.5,6.19,"A source sends four symbols with these chances."],[6.44,12.29,"A typical eight: A four times, B twice."],[12.54,18.07,"Each one costs its surprise in bits."],[18.32,23.77,"A fixed 2-bit code: 16 bits. Surprise: only 14."],[24.02,30.91,"1.75 bits a symbol: the floor, if nothing is lost."]],"warp":[[0,0],[0.5,0.4],[6.44,2.5],[12.54,4.5],[18.32,9],[24.02,11.2],[31.719,13.2]]},{"dur":29.93,"caps":[[0.5,3.47,"Codes sit side by side, with no gaps."],[3.72,7.89,"01 could be A then B…"],[8.14,11.67,"…or C. Two readings!"],[11.92,15.61,"Fix it: no code may start another."],[15.86,18.67,"Put every code at a branch end."],[18.92,25.33,"Follow the bits down. A leaf means a letter is done."],[25.58,28.15,"No code starts another."]],"warp":[[0,0],[0.5,0.4],[3.72,2.4],[8.14,3.8],[11.92,5.7],[15.86,7.3],[18.92,9],[25.58,11.9],[29.93,13.4]]},{"dur":26.657,"caps":[[0.5,5.15,"Each letter has a chance. Join the two smallest."],[5.4,10.05,"Letters under it pay one more bit: +.20."],[10.3,14.39,"Repeat with the two smallest left."],[14.64,18.89,"One node left: the tree is done."],[19.14,24.99,"1.98 bits a letter. This source's floor is 1.96."]],"warp":[[0,0],[0.5,0.4],[5.4,3],[10.3,5.5],[14.64,9.4],[19.14,11.1],[26.657,14]]},{"dur":26.68,"caps":[[0.77,4.3,"Common B sits one step from the root."],[4.55,10.96,"The path down is the code."],[11.21,17.3,"Spell BBADEBC with these codes."],[17.55,21.32,"15 bits instead of 21."],[21.57,25.58,"Joined up, it still splits into the same codes."]],"warp":[[0,0],[0.77,1.4],[4.55,2.9],[11.21,5.6],[17.55,9.6],[21.57,11],[26.68,12.9]]},{"dur":31.718,"caps":[[0.5,6.59,"No chances needed: it starts with just A and B."],[6.84,11.89,"Phrase plus next letter new? Send a code, learn it."],[12.14,18.07,"Known? Keep growing. New? Send and learn."],[18.32,21.93,"Same again: grow while known, send when new."],[22.18,26.43,"Known again, then the text ends: send it."],[26.68,30.21,"Nine letters became five codes."]],"warp":[[0,0],[0.5,0.4],[6.84,2.9],[12.14,5.7],[18.32,8],[22.18,11.3],[26.68,13.1],[31.718,14.4]]},{"dur":24.961,"caps":[[0.5,4.83,"Only codes arrive, plus the A, B start."],[5.08,10.85,"Each code adds an entry: previous plus first letter."],[11.1,17.83,"Code 4 is not in yet: AB plus AB's first letter."],[18.08,23.13,"Same text back. No dictionary sent."]],"warp":[[0,0],[0.5,0.9],[5.08,4.3],[11.1,7.8],[18.08,10.8],[24.961,13.2]]},{"dur":27.075,"caps":[[0.5,4.91,"A GIF packs each row of pixels with LZW."],[5.16,10.21,"Each piece of the row gets one code."],[10.46,14.87,"Repeats share codes: 18 pixels, 11 codes."],[15.12,20.97,"Noise rarely repeats, so it saves little."],[21.22,25.63,"LZW feeds on repeats."]],"warp":[[0,0],[0.5,0.4],[5.16,2.6],[10.46,6.1],[15.12,7.7],[21.22,10.7],[27.075,12.5]]},{"dur":13.328,"caps":[],"warp":[[0,0],[0.5,0.9],[4.52,2],[8.7,3.1],[13.328,9]]}]};
